;   // Create a new HardwareSerial class\n\n// can also try hardware serial with\nHumanStaticLite radar = HumanStaticLite(&MySerial);\n\nvoid setup() {\n  // put your setup code here, to run once:\n  Serial.begin(115200);\n\n  /*\n   * 4, 5 indicate GPIO4 and GPIO5, corresponding to pins D2 and D3. \n   * If you want to use the hardware UART pins of the XIAO ESP32C3 directly, you can change 4, 5 to -1, -1.\n   * MySerial.begin(115200, SERIAL_8N1, -1, -1);\n   * \n   * In addition to this you can also use the D9 (GPIO9) and D10 (GPIO10) pins as serial ports.\n   * MySerial1.begin(115200, SERIAL_8N1, 9, 10);\n   */\n  MySerial.begin(115200, SERIAL_8N1, 4, 5);\n\n  while(!Serial);   //When the serial port is opened, the program starts to execute.\n\n  delay(500);\n\n  Serial.println("Ready");\n}\n\nvoid loop() {\n  // put your main code here, to run repeatedly:\n  radar.recvRadarBytes();           //Receive radar data and start processing\n  radar.showData();                 //Serial port prints a set of received data frames\n  delay(200);                       //Add time delay to avoid program jam\n}\n'})}),"\n",(0,s.jsx)(n.h2,{id:"\u6545\u969C\u6392\u9664",children:"\u6545\u969C\u6392\u9664"}),"\n",(0,s.jsx)(n.h3,{id:"faq1",children:"\u5E38\u89C1\u95EE\u9898 1\uFF1A\u6B64\u4F20\u611F\u5668\u80FD\u5426\u5728\u540C\u4E00\u73AF\u5883\u4E2D\u540C\u65F6\u68C0\u6D4B\u591A\u4E2A\u4EBA\uFF1F"}),"\n",(0,s.jsxs)(n.blockquote,{children:["\n",(0,s.jsx)(n.p,{children:"\u7B54\uFF1A\u4E0D\u53EF\u4EE5\u3002\u6B64\u4F20\u611F\u5668\u53EA\u80FD\u7528\u4E8E\u5355\u4E2A\u751F\u7269\u4F53\u3002\u5982\u679C\u76D1\u6D4B\u8303\u56F4\u5185\u6709\u591A\u4E2A\u4EBA\u6216\u52A8\u7269\uFF0C\u8FD9\u5C06\u5F71\u54CD\u76D1\u6D4B\u7ED3\u679C\u3002"}),"\n"]}),"\n",(0,s.jsx)(n.h3,{id:"faq2",children:"\u5E38\u89C1\u95EE\u9898 2\uFF1A\u4E3A\u4EC0\u4E48\u6211\u5728 XIAO ESP32C3 \u7684\u4E32\u53E3\u76D1\u89C6\u5668\u4E2D\u770B\u4E0D\u5230\u4EFB\u4F55\u5185\u5BB9\uFF1F"}),"\n",(0,s.jsxs)(n.blockquote,{chil